import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createStore } from "./store.js";

const root = dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT) || 3000;
const store = createStore(process.env.BOOKS_FILE || join(root, "data", "books.json"));

const html = await readFile(join(root, "public", "index.html"), "utf8");

function send(res, status, body, type = "application/json; charset=utf-8") {
  res.writeHead(status, {
    "Content-Type": type,
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function sendJson(res, status, value) {
  send(res, status, JSON.stringify(value));
}

async function readJson(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error("Request body is too large");
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  if (chunks.length === 0) return {};
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8"));
  } catch {
    const error = new Error("Invalid JSON");
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url || "/", "http://localhost");
    const bookMatch = url.pathname.match(/^\/api\/books\/([^/]+)$/);

    if (req.method === "GET" && (url.pathname === "/" || url.pathname === "/book")) {
      send(res, 200, html, "text/html; charset=utf-8");
      return;
    }

    if (req.method === "GET" && url.pathname === "/api/books") {
      sendJson(res, 200, { books: await store.list() });
      return;
    }

    if (req.method === "POST" && url.pathname === "/api/books") {
      const book = await store.add(await readJson(req));
      sendJson(res, 201, { book });
      return;
    }

    if (req.method === "GET" && bookMatch) {
      const book = await store.get(decodeURIComponent(bookMatch[1]));
      if (!book) {
        sendJson(res, 404, { error: "Book not found" });
        return;
      }
      sendJson(res, 200, { book });
      return;
    }

    if (req.method === "POST" && bookMatch && url.pathname.endsWith("/finish") === false) {
      sendJson(res, 404, { error: "Not found" });
      return;
    }

    const finishMatch = url.pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finishMatch) {
      const book = await store.finish(decodeURIComponent(finishMatch[1]));
      if (!book) {
        sendJson(res, 404, { error: "Book not found" });
        return;
      }
      sendJson(res, 200, { book });
      return;
    }

    sendJson(res, 404, { error: "Not found" });
  } catch (error) {
    const status = error.status || (error.message === "Title is required" || error.message === "Author is required" ? 400 : 500);
    sendJson(res, status, { error: status === 500 ? "Something went wrong" : error.message });
  }
});

server.listen(port, () => {
  console.log(`Reading list at http://localhost:${port}`);
});

