  </head>
  <body>
    <main>
      <div id="list-view">
        <h1>Reading list</h1>
        <p class="lede">What you're reading now, and what you've finished.</p>

        <form id="add-form">
          <label>Title <input name="title" required maxlength="200" /></label>
          <label>Author <input name="author" required maxlength="200" /></label>
          <label>Notes <textarea name="notes" maxlength="4000"></textarea></label>
          <div class="row">
            <button type="submit">Add book</button>
          </div>
          <p class="error" id="form-error"></p>
        </form>

        <section>
          <h2>Currently reading</h2>
          <ul id="reading"></ul>
        </section>
        <section>
          <h2>Finished</h2>
          <ul id="finished"></ul>
        </section>
      </div>

      <div id="detail-view" class="hidden">
        <p><a href="/">← All books</a></p>
        <article class="detail" id="detail"></article>
      </div>
    </main>
    <script>
      const listView = document.querySelector("#list-view");
      const detailView = document.querySelector("#detail-view");
      const readingList = document.querySelector("#reading");
      const finishedList = document.querySelector("#finished");
      const form = document.querySelector("#add-form");
      const formError = document.querySelector("#form-error");
      const detail = document.querySelector("#detail");

      function bookIdFromPath() {
        const match = location.pathname.match(/^\/book\/([^/]+)$/);
        return match ? decodeURIComponent(match[1]) : null;
      }

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;");
      }

      function renderList(books) {
        const reading = books.filter((book) => book.status !== "finished");
        const finished = books.filter((book) => book.status === "finished");
        readingList.innerHTML = reading.length
          ? reading.map(card).join("")
          : `<li class="empty">Nothing in progress.</li>`;
        finishedList.innerHTML = finished.length
          ? finished.map(card).join("")
          : `<li class="empty">No finished books yet.</li>`;
      }

      function card(book) {
        const finish = book.status === "finished"
          ? ""
          : `<button type="button" class="quiet" data-finish="${escapeHtml(book.id)}">Mark finished</button>`;
        return `<li class="card">
          <div>
            <a class="title" href="/book/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>
            <div class="meta">${escapeHtml(book.author)}</div>
          </div>
          ${finish}
        </li>`;
      }

      async function loadList() {
        const response = await fetch("/api/books");
        const data = await response.json();
        renderList(data.books || []);
      }

      async function showDetail(id) {
        listView.classList.add("hidden");
        detailView.classList.remove("hidden");
        const response = await fetch("/api/books/" + encodeURIComponent(id));
        if (!response.ok) {
          detail.innerHTML = `<p>This book isn't in the list.</p>`;
          return;
        }
        const { book } = await response.json();
        const notes = book.notes ? escapeHtml(book.notes) : "No notes yet.";
        const share = location.origin + "/book/" + encodeURIComponent(book.id);
        detail.innerHTML = `
          <h1>${escapeHtml(book.title)}</h1>
          <p class="meta">${escapeHtml(book.author)} · ${book.status === "finished" ? "Finished" : "Currently reading"}</p>
          <p class="notes">${notes}</p>
          <p class="meta">Share this book: <a href="${escapeHtml(share)}">${escapeHtml(share)}</a></p>
        `;
        document.title = book.title;
      }

      form.addEventListener("submit", async (event) => {
        event.preventDefault();
        formError.textContent = "";
        const body = {
          title: form.title.value,
          author: form.author.value,
          notes: form.notes.value,
        };
        const response = await fetch("/api/books", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(body),
        });
        const data = await response.json();
        if (!response.ok) {
          formError.textContent = data.error || "Could not add the book.";
          return;
        }
        form.reset();
        await loadList();
      });

      document.addEventListener("click", async (event) => {
        const button = event.target.closest("[data-finish]");
        if (!button) return;
        button.disabled = true;
        await fetch("/api/books/" + encodeURIComponent(button.dataset.finish) + "/finish", {
          method: "POST",
        });
        await loadList();
      });

      const id = bookIdFromPath();
      if (id) showDetail(id);
      else loadList();
    </script>
  </body>
</html>
"}

