import { readFile, rename, writeFile } from "node:fs/promises";

export function createStore(filePath) {
  let queue = Promise.resolve();

  function withLock(fn) {
    const run = queue.then(fn, fn);
    queue = run.then(
      () => undefined,
      () => undefined,
    );
    return run;
  }

  async function readBooks() {
    try {
      const raw = await readFile(filePath, "utf8");
      const parsed = JSON.parse(raw);
      if (!parsed || !Array.isArray(parsed.books)) return [];
      return parsed.books;
    } catch (error) {
      if (error && error.code === "ENOENT") return [];
      throw error;
    }
  }

  async function writeBooks(books) {
    const payload = JSON.stringify({ books }, null, 2) + "\n";
    const tempPath = `${filePath}.${process.pid}.tmp`;
    await writeFile(tempPath, payload, "utf8");
    await rename(tempPath, filePath);
  }

  return {
    filePath,

    list() {
      return withLock(() => readBooks());
    },

    get(id) {
      return withLock(async () => {
        const books = await readBooks();
        return books.find((book) => book.id === id) ?? null;
      });
    },

    add(input) {
      return withLock(async () => {
        const title = clean(input?.title);
        const author = clean(input?.author);
        const notes = typeof input?.notes === "string" ? input.notes.trim() : "";
        if (!title) throw new Error("Title is required");
        if (!author) throw new Error("Author is required");

        const books = await readBooks();
        const book = {
          id: randomUUID(),
          title,
          author,
          notes,
          status: "reading",
          createdAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await writeBooks(books);
        return book;
      });
    },

    finish(id) {
      return withLock(async () => {
        const books = await readBooks();
        const book = books.find((item) => item.id === id);
        if (!book) return null;
        if (book.status !== "finished") {
          book.status = "finished";
          book.finishedAt = new Date().toISOString();
          await writeBooks(books);
        }
        return book;
      });
    },
  };
}

function clean(value) {
  return typeof value === "string" ? value.trim() : "";
}

import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createStore } from "./store.js";

const root = dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT) || 3000;
const store = createStore(process.env.BOOKS_FILE || join(root, "data", "books.json"));

const html = await readFile(join(root, "public", "index.html"), "utf8");

function send(res, status, body, type = "application/json; charset=utf-8") {
  res.writeHead(status, {
    "Content-Type": type,
    "Cache-Control": "no-store",
  });
  res.end(body);
}

function sendJson(res, status, value) {
  send(res, status, JSON.stringify(value));
}

async function readJson(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error("Request body is too large");
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  if (chunks.length === 0) return {};
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8"));
  } catch {
    const error = new Error("Invalid JSON");
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url || "/", "http://localhost");
    const bookMatch = url.pathname.match(/^\/api\/books\/([^/]+)$/);

    if (req.method === "GET" && (url.pathname === "/" || url.pathname === "/book")) {
      send(res, 200, html, "text/html; charset=utf-8");
      return;
    }

    if (req.method === "GET" && url.pathname === "/api/books") {
      sendJson(res, 200, { books: await store.list() });
      return;
    }

    if (req.method === "POST" && url.pathname === "/api/books") {
      const book = await store.add(await readJson(req));
      sendJson(res, 201, { book });
      return;
    }

    if (req.method === "GET" && bookMatch) {
      const book = await store.get(decodeURIComponent(bookMatch[1]));
      if (!book) {
        sendJson(res, 404, { error: "Book not found" });
        return;
      }
      sendJson(res, 200, { book });
      return;
    }

    if (req.method === "POST" && bookMatch && url.pathname.endsWith("/finish") === false) {
      sendJson(res, 404, { error: "Not found" });
      return;
    }

    const finishMatch = url.pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
    if (req.method === "POST" && finishMatch) {
      const book = await store.finish(decodeURIComponent(finishMatch[1]));
      if (!book) {
        sendJson(res, 404, { error: "Book not found" });
        return;
      }
      sendJson(res, 200, { book });
      return;
    }

    sendJson(res, 404, { error: "Not found" });
  } catch (error) {
    const status = error.status || (error.message === "Title is required" || error.message === "Author is required" ? 400 : 500);
    sendJson(res, status, { error: status === 500 ? "Something went wrong" : error.message });
  }
});

