import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { createStore } from "./store.js";

let dir;

afterEach(async () => {
  if (dir) await rm(dir, { recursive: true, force: true });
});

async function freshStore() {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  return createStore(join(dir, "books.json"));
}

describe("book store", () => {
  it("starts empty when the file is missing", async () => {
    const store = await freshStore();
    expect(await store.list()).toEqual([]);
  });

  it("adds a book and keeps it after a new store opens the same file", async () => {
    const store = await freshStore();
    const added = await store.add({
      title: "  The Left Hand of Darkness  ",
      author: "Ursula K. Le Guin",
      notes: "Winter.",
    });

    expect(added.status).toBe("reading");
    expect(added.title).toBe("The Left Hand of Darkness");

    const reopened = createStore(store.filePath);
    const books = await reopened.list();
    expect(books).toHaveLength(1);
    expect(books[0].id).toBe(added.id);
    expect(books[0].notes).toBe("Winter.");
  });

  it("marks a book finished and can load it by id", async () => {
    const store = await freshStore();
    const added = await store.add({ title: "Piranesi", author: "Susanna Clarke" });
    const finished = await store.finish(added.id);
    expect(finished.status).toBe("finished");
    expect(finished.finishedAt).toEqual(expect.any(String));
    expect(await store.get(added.id)).toMatchObject({ status: "finished" });
    expect(await store.finish("missing")).toBeNull();
  });

  it("rejects a book without a title or author", async () => {
    const store = await freshStore();
    await expect(store.add({ title: "  ", author: "Someone" })).rejects.toThrow(/title/i);
    await expect(store.add({ title: "Named", author: "" })).rejects.toThrow(/author/i);
  });
});

